const e={icmarkets:{jiaoyi2250cfd:"2250개 이상의 CFD 거래",dianchadizhi0:"스프레드 0.0핍부터",lijikaishijiaoyi:"지금 거래 시작하기",zijinzairisxian:"귀하의 자금은 위험에 처해 있습니다",yuanyoudiancha:"원시 스프레드로 거래하세요",zhenshide0:"숨겨진 수수료 없는 원시 스프레드",chixuxiaobaodiancha:"다양한 유동성 공급으로 24/5 내내 좁은 스프레드 유지",kaicelijiaochakan:"가격 개요",gongyingduandilacixian:"저지연 광섬유 연결",yuanjiageyouyi:"원시 가격의 장점",qiangdaduan:"강력한 거래 터미널",jiaoyipingtai:"플랫폼",shijierongzaishouzhi:"전 세계 시장을 손안에",ngechanpin:"{n}개 상품",waihuicfd:"외환 CFD",shangpincfd:"상품 CFD",gupiaocfd:"주식 CFD",zhishucfd:"지수 CFD",zhaiquancfd:"채권 CFD",biquancfd:"암호화폐 CFD",qihuo:"선물 CFD",chanpinfanwei:"상품 범위",nidezijinnidefangshi:"당신의 자금, 당신의 방식",lijichongzhi:"즉시 입금",kuaijitixian:"빠른 출금",wushouxufei:"수수료 0%",zhifufangshi:"결제 방법",gengduochongtixian:"입금, 출금 및 계좌 자금에 대한 자세한 정보 보기",qingdianjizheli:"여기를 클릭하세요",sibujikaizhuzhanghu:"단 4단계로 계좌 개설",zhuce:"등록",xuanzezhuce:"계좌 유형 선택 및 신청서 작성",renzheng:"인증",jiashurenzheng:"디지털 인증 시스템으로 빠른 확인",chongzhi:"입금",jiaoyizhanghuchongzhi:"다양한 방법으로 계좌에 자금 추가",huodao2100zhong:"실계좌로 거래하고 2,100개 이상의 상품 이용",kaihuzhanghu:"계좌 개설",zijinfengxian:"*귀하의 자금은 위험에 노출되어 있습니다",lijijiaoyi:"지금 거래 시작",youzhiyitiaojian:"우수한 거래 조건으로 거래",qidong:"시작하기",mianfeiceshi:"무료 데모 체험",rawspreadmiaoshu:"원초적인 스프레드는 여러분이 기다려온 차이입니다. 0.0핍부터 시작하는 스프레드로 거래하세요. 재호가 없음, 가격 조작 없음, 제한 없음. {name}는 대량 거래자, 스캘퍼 및 자동매매 트레이더가 선택한 외환 브로커입니다.",spread0:"0.0핍부터 시작하는 스프레드",trade:"거래",kuaijiexec:"빠른 주문 실행",execspeed:"평균 실행 속도 66ms 이하",jigoulirun:"기관급 유동성",wuchongfushengliudongxing:"유동성 재사용 없음으로 슬리피지 최소화",pipspread:"핍 스프레드",leverageupto:"최대 레버리지",microlot:"마이크로 랏 거래",tradableinstruments:"거래 가능한 상품",dedicatedsupport:"전담 지원",sevendays:"7일"},homeCmc318:{heroTitle:"수상 경력이 있는 CFD 트레이딩 경험",heroDesc:"외환, 지수, 상품, 암호화폐, 주식 등에 레버리지로 거래하세요. 세계적으로 유명한플랫폼에서 주요 시장에 접근하거나, 강력한 웹 플랫폼과 모바일 앱, 또는 TradingView 통합에서 13,000개 이상의 상품을 선택하세요.",heroTrust1:"1989년 설립",heroTrust2:"200만 이상의 글로벌 고객",heroTrust3:"FTSE 250 그룹",heroRatingGreat:"훌륭함",heroRatingScore:"4.2 / 5",heroRatingBrand:"Trustpilot",heroBtnPrimary:"MetaTrader 계좌 개설",heroBtnOutline:"로그인",heroStatSpread:"FX 최소 raw 스프레드",heroStatLeverage:"최대 리테일 레버리지",heroStatLot:"마이크로 로트 거래",heroStatInstruments:"금융 상품",heroStatSupport:"전담 고객 지원",heroStatNote:"*표준 로트의 1/100 크기로 거래",whyTitle:"왜 CMC Markets를 선택해야 할까요?",whyCard1Title:"런던 기반 서버",whyCard1Desc:"런던 기반 서버와 업계 명성을 통해 최상위 유동성 솔루션을 제공하여 일관되게 번개 같은 체결 속도를 제공합니다.",whyCard2Title:"35년 이상의 경험",whyCard2Desc:"1989년에 설립된 CMC Markets는 글로벌 기업의 안정성과 재무적 힘을 바탕으로 고객에게 현지 전문성을 제공합니다.",whyCard3Title:"제한 없는 거래",whyCard3Desc:"MetaTrader 플랫폼은 최소 손절매 또는 이익 실현 거리와 제한이 없어 고빈도 트레이더에게 특히 유용합니다.",whyCard4Title:"무료 프리미엄 지표 및 EA",whyCard4Desc:"무료 추가 프리미엄 지표 및 EA 세트로 기술적 분석을 갈고닦으세요.",whyCard5Title:"빠르고 안전한 암호화폐 결제",whyCard5Desc:"Binance Pay를 통해 USDT와 USDC로 계좌 입출금이 가능합니다.",whyCard6Title:"장외 시간 거래",whyCard6Desc:"몇 차례의 휴장 시간을 제외하고 주 5일, 24시간 지수, 외환, 상품, 암호화폐 CFD를 거래할 수 있습니다.",instrumentsTitle:"거래 상품",instrumentsTabBlock:"대宗商品",instrumentsTabCrypto:"암호화폐",instrumentsHeaderInstrument:"상품",instrumentsHeaderPrice:"가격",instrumentsHeaderVolume:"거래량",instrumentsHeaderChange:"24시간 변동",instrumentsLoading:"로드 중...",instrumentsNoData:"데이터 없음",instrumentsNote:"가격은 참고용입니다. 과거 실적은 미래 결과의 신뢰할 수 있는 지표가 아닙니다.",downloadTitle:"CMC의 새로운 시대",downloadDesc:"수상 경력이 있는 플랫폼에 1억 파운드 이상을 투자하여 모든 트레이딩 스타일에 맞는 독자적인 기술을 만들었습니다.",downloadFeature1:"TradingView 차트 통합",downloadFeature2:"고급 주문 체결",downloadFeature3:"최적화된 모바일 플랫폼",downloadFeature4:"TipRanks 분석",downloadFeature5:"고객 심리 추적기",downloadFeature6:"패턴 인식 스캐너",downloadFeature7:"Morningstar 주식 리서치 및 Reuters 뉴스",downloadBtnPrimary:"당사 플랫폼에서 거래",downloadMobileTitle:"모바일",downloadMobileDesc:"강력하면서도 직관적이어서 모든 트레이더에게 적합합니다. 트레이딩 여정의 다음 단계가 어디든 모바일 플랫폼이 도와드립니다.",downloadQrText:"QR 코드를 스캔하여 앱을 다운로드하세요.",downloadDesktopTitle:"데스크톱",downloadDesktopDesc:"온라인 트레이딩 플랫폼은 강력하고 직관적으로 설계되었습니다. 최첨단 기능과 보안, 빠른 체결, 일류 인사이트 및 분석을 결합합니다. 모든 전략을 지원하도록 구축되었습니다.",downloadDesktopBtn:"플랫폼 체험",reliabilityTitle:"우수한 체결과 신뢰성",reliabilityDesc:"선구적인 기술과 높이 평가받는 고객 서비스, 강력한 플랫폼 선택권을 결합하여 진지한 트레이더에게 이상적인 조합을 제공합니다.",reliabilityCard1Value:"100%",reliabilityCard1Name:"자동 체결",reliabilityCard1Info:"딜러 개입 없이 거래가 체결됩니다.",reliabilityCard2Value:"99.29%",reliabilityCard2Name:"체결율",reliabilityCard2Info:"재견적 없이, 가능한 한 보신 가격대로 주문을 이행합니다.",reliabilityCard3Value:"99.95%",reliabilityCard3Name:"플랫폼 안정성",reliabilityCard3Info:"거의 100%의 핵심 플랫폼 가동 시간을 일관되게 달성하여 트레이딩에 집중할 수 있습니다.",reviewsTitle:"다른 트레이더는 CMC Markets에 대해 무엇을 말하나요?",reviewsDesc:"금융 서비스의 선구자로서 뛰어난 기술과 35년의 업계 노하우를 결합합니다. 그것이 200만 명 이상의 글로벌 트레이더와 투자자가 우리를 신뢰하는 이유입니다.",reviewsBadge:"초대됨",review1Title:"거의 20년간 거래...",review1Text:"거의 20년간 거래하면서 직원들이 매우 도움이 되고 인내심이 있었습니다...",review1Author:"Johannes, 1일 전",review2Title:"좋은 고객 서비스",review2Text:"좋은 고객 서비스. 거래 상품 범위가 넓습니다",review2Author:"Fred, 1일 전",review3Title:"많은 것을 배우고 있음",review3Text:"많은 것을 배우고 있음",review3Author:"Hamid, 2일 전",review4Title:"사용하기 쉬운 플랫폼",review4Text:"사용하기 쉬운 플랫폼",review4Author:"Chris Colbourne 님, 3일 전",review5Title:"대부분 잘 작동함",review5Text:"대부분 잘 작동함, 정직한 회사, 투명한 가격, 괜찮은 플랫폼, 좋은 고객 서비스...",review5Author:"Ali M, 4일 전",reviewsFooter:"3,252개 리뷰 기준 4.2 / 5 평가. 5성 리뷰를 표시합니다.",reviewsTrustpilot:"Trustpilot",joinTitle:"200만 명 이상의 글로벌 트레이더와 투자자에 참여하세요",joinStep1Title:"실제 계좌 신청",joinStep1Desc:"몇 가지 간단한 단계로 계좌를 신청하고 검증할 수 있습니다.",joinStep2Title:"계좌 입금",joinStep2Desc:"카드, 은행 송금, Binance Pay 암호화폐, 또는 Neteller와 Skrill 같은 결제 서비스 제공업체를 통해 원활하게 입금하세요.",joinStep3Title:"거래 체결",joinStep3Desc:"Next Generation 트레이딩 플랫폼에서 13,000개 이상의 글로벌 상품을 원터치로 거래하세요.",joinBtn:"계좌 개설",partnerTitle:"CMC Markets 파트너 되기",partnerDesc:"업계를 선도하는 CFD 및 외환 브로커와 파트너가 되세요. 고급 IB 포털 보고 기능과 높은 고객 전환율을 통해 비즈니스 성장을 돕도록 설계된 프로그램입니다. 다계층 및 맞춤형 거래 및 결제 구조 지원을 포함한 넉넉한 보수를 받을 수 있습니다. 오늘 당사 경험丰富的 지역 담당자와 이야기하려면 연락주세요.",partnerBtnPrimary:"파트너 되기",partnerBtnOutline:"파트너 포털 로그인",faqTitle:"우리가 하는 모든 것에 투명성을",faqDesc:"개인이든 기업이든 고객이 우리의 비즈니스 모델과 CMC Markets가 제공할 수 있는 가치를 이해하는 것이 중요하다고 믿습니다.",faqQ1:"계좌를 어떻게 개설하나요?",faqA1:"원하는 트레이딩 플랫폼을 결정하면 여기에서 플랫폼 계좌를 신청하거나 Next Generation 계좌를 신청할 수 있습니다. 두 플랫폼 모두에서 거래하려면 각각 별도로 신청해야 합니다.",faqQ2:"실수로 Next Generation 기반 플랫폼 계좌를 개설했습니다. MetaTrader 기반 계좌를 어떻게 개설하나요?",faqA2:"두 플랫폼은 별도로 운영되므로 여기에서 플랫폼 계좌를 신청해야 합니다.",faqQ3:"실제 계좌 신청에 어떤 서류가 필요하나요?",faqA3:"CMC Markets는 다양한 신분증 및 주소증명 서류를 읽을 수 있는 기술을 사용합니다. 일반적으로 여권과 같은 공식 신분증과 공공요금 고지서 또는 은행 거래 명세서와 같은 주소증명 서류가 필요합니다. 검증 단계에서 전자 버전을 업로드하라는 메시지가 표시됩니다.",faqQ4:"실제 계좌 신청 전에 데모 계좌를 개설할 수 있나요?",faqA4:"네, 모든 플랫폼에서 무료 데모 계좌를 제공합니다. 데모 계좌는 가상 자금으로 거래 연습을 할 수 있는 계좌이므로 자신의 자금은 위험에 노출되지 않습니다. 플랫폼 데모 계좌를 만들거나 Next Generation 데모 계좌를 신청할 수 있습니다. 데모 계좌는 최초 30일간 유효합니다. 30일간 로그인하지 않으면 만료됩니다. Next Generation 데모 계좌는 만료일이 없습니다.",faqQ5:"CMC Markets는 어떤 계좌 유형을 제공하나요?",faqA5_1:"표준 CFD 트레이딩 계좌와 FX Active 트레이딩 계좌가 있습니다. FX Active 계좌는 6개 주요 통화쌍(XAU/USD、XAG/USD、XPT/USD、XPD/USD、XBR/USD、XTI/USD、NATGAS/USD)에서 0.0핍 스프레드를 제공하며 0.03% 수수료를 부과합니다.",faqA5_2:"FX Active는 활발한 외환 트레이더를 위해 설계되었지만 지수, 주식(Next Generation 플랫폼만 해당), 상품, 암호화폐 등 다른 모든 상품도 포함됩니다.",faqQ6:"실제 트레이딩 계좌의 최소 입금액은 얼마인가요?",faqA6:"계좌 개설에는 최소 입금이 필요하지 않습니다. 그러나 포지션을 커버할 만큼 충분한 자금이 입금되기 전까지는 거래 주문을 할 수 없습니다.",faqQ7:"계좌에 어떻게 입금하나요?",faqA7:"신용카드, 온라인 뱅킹 등 다양한 결제 수단을 제공합니다. 입금 수단의 전체 목록을 보려면 클라이언트 포털에 로그인하여 자금 옵션을 확인하세요.",faqQ8:"CMC Markets는 제휴, 추천 또는 소개자 인센티브를 제공하나요?",faqA8_1:"네, CMC Markets에 고객을 소개하는 소개자 및 파트너에게 보상을 제공하는 프로그램이 있습니다. 제휴 회원으로서 신규 고객을 소개하면 커미션을 받을 수 있습니다. 커미션율은 추천 고객의 국가에 따라 다릅니다. 소개자로서 고객의 거래 활동에 기반하여 커미션을 받습니다. CMC Markets는 수익성을 극대화하기 위한 다계층 리베이트 구조를 포함하여 유연하고 경쟁력 있는 리베이트 구조를 제공합니다.",faqA8_2:"여기에서 CMC Markets 소개자 프로그램에 신청",faqQ9:"CMC Markets는 규제를 받나요?",faqA9:"CMC Markets는 영국, 호주, 독일, 캐나다, 뉴질랜드, 싱가포르, 버뮤다를 포함한 전 세계 15개 사무소를 보유하고 있습니다. CMC Markets의 각 법인은 현지 당국에 의해 라이선스 및 규제를 받으며, 예를 들어 CMC Markets Bermuda는 버뮤다 금융당국(BMA)에서 투자 사업 및 디지털 자산 사업 라이선스를 받았습니다.",faqQ10:"CMC Markets는 내 자금을 어떻게 보호하나요?",faqA10:"CMC Markets의 고객으로서, 귀하의 자금은 CMC Markets의 자기 자금과 별도로 보관됩니다. 주요 은행에 분산된 분리된 고객 은행 계좌에 보관되며, 위험 기준에 따라 정기적으로 평가됩니다. BMA 규칙에 따라 소매 고객에게는 마이너스 잔액 보호가 제공되어야 합니다. 이는 귀하의 최대 손실이 당사에 입금한 금액을 초과하지 않는다는 의미입니다.",faqQ11:"거래를 어떻게 체결하나요?",faqA11_1:"플랫폼에서 거래하는 경우 거래하려는 상품을 선택하세요(PC에서 더블클릭). 새 주문 창이 나타납니다. 원하는 거래량(로트 단위)을 입력하고 손절매 또는 이익 실현과 같은 리스크 관리 주문을 추가합니다. 그런 다음 거래하려는 방향으로 시장 주문을 내세요: 매수로 롱, 매도로 숏. 플랫폼에서 주문 방법은 여러 가지가 있습니다. 플랫폼 기능에 대해 자세히 알아보려면 도움말 > 도움말 주제 또는 도움말 > 동영상 가이드를 참조하세요.",faqA11_2:"Next Generation 플랫폼에서 거래하는 경우 제품 라이브러리에서 원하는 상품을 검색하세요. 선택한 상품을 선택하세요(PC에서 우클릭)하고 '주문 티켓'을 선택합니다. 주문 티켓 상자에서 주문 유형(시장, 지정가, 스톱 엔트리)을 선택하고 거래량을 단위 또는 금액으로 입력합니다(메인 탐색의 '설정' 메뉴에서 구성 가능). 리스크를 최소화하기 위한 손절매 및 이익 실현 수준을 추가하고 롱 또는 숏에 따라 'BUY' 또는 'SELL'을 선택합니다. 준비가 되면 'Place Buy Market Order' 또는 'Place Sell Market Order'를 선택합니다.",faqQ12:"CMC Markets가 제공하는 최대 레버리지는 얼마인가요?",faqA12:"소매 고객의 경우 현재 CFD 트레이딩 및 FX Active 계좌에서 거래할 수 있는 최대 레버리지는 100:1 입니다.",faqQ13:"TradingView란 무엇인가요?",faqA13:"TradingView는 차트를 보고, 추세를 분석하고, 온라인 커뮤니티와 상호 작용할 수 있는 트레이딩 리서치 플랫폼입니다. TradingView 계정과 CMC Markets 계정을 연결하면 TradingView 내에서 포지션을 개설, 관리, 청산할 수 있습니다. TradingView에 대해 자세히 알아보려면 여기를 클릭하세요.",faqQ14:"MT4, MT5, TradingView 및 CMC 트레이딩 플랫폼의 주요 차이점은 무엇인가요?",faqA14_1:"MetaQuotes는 전 세계적으로 인기 있는 외환 및 CFD 트레이딩 플랫폼입니다. TradingView는 브로커 계정에 연결하여 거래할 수 있는 트레이딩 및 차트 플랫폼입니다. 당사의 독점 웹 기반 플랫폼은 기능이 풍부하고 12,000개 이상의 CFD 상품에 접근할 수 있습니다.",faqA14_2:"각 플랫폼에서는 CFD 트레이딩 또는 FX Active 계좌를 선택할 수 있습니다. FX Active 계좌는 6개 주요 통화쌍에서 0.0핍 스프레드를 제공하고 다른 모든 통화쌍에서 25% 스프레드 할인을 제공합니다. 고정 낮은 커미션은 10만 달러 명목 가치당 2.50달러입니다.",faqA14_3:"당사 트레이딩 플랫폼은 다운로드가 필요하지 않지만, 플랫폼는 알고리즘 트레이딩(전문가 자문사를 통해) 및 MQL4 및 MQL5 커뮤니티를 통한 소셜 트레이딩과 같은 기능을 완전히 활용하기 위해 다운로드가 필요합니다.",faqA14_4:"MetaTrader 플랫폼은 기본적으로 헤지 포지션을 제공하고, CMC 트레이딩 플랫폼은 기본적으로 넷 포지션을 제공합니다.",faqQ15:"MetaTrader에서 헤지 포지션을 가질 수 있나요?",faqA15:"네, 반대, 관련 또는 대체 거래를 개설할 수 있으며 전문가 자문사를 사용하는 트레이더에게 중단을 주지 않습니다.",faqQ16:"자금을 어떻게 인출하나요?",faqA16:"플랫폼 클라이언트 포털 또는 당사 트레이딩 플랫폼에 로그인하여 자금 섹션의 안내를 따르세요.",faqQ17:"비밀번호를 재설정하려면 어떻게 하나요?",faqA17:"여기에서 플랫폼 계좌 비밀번호를 재설정하고, 여기에서 Next Generation 계좌 비밀번호를 재설정할 수 있습니다.",faqQ18:"CMC Markets의 불만 처리 절차는 어떻게 되나요?",faqA18:"우리는 항상 모든 고객에게 높은 수준의 서비스를 제공하는 것을 목표로 합니다. 모든 피드백을 소중히 여기며 제품과 서비스 개선에 활용합니다. 때때로 문제가 발생하거나 오해가 생길 수 있다는 점을 인식합니다. 우리는 문의와 불만을 적극적이고 동정심 있게 처리하기 위해 노력합니다. 당사에 책임이 있는 경우 가능한 한 빨리 바로잡기 위해 노력합니다. 불만 처리 절차는 여기에서 확인하거나. 모든 문의와 불만은 영어로 처리됨에 유의하세요.",readyLabel:"CFD 거래",readyTitle:"시작할 준비가 되셨나요?",readyDesc1:"이미 계좌가 있으시면 선택한 플랫폼에 로그인하세요.",readyDesc2:"계좌가 아직 없으신가요? 지금 계좌를 개설하세요.",readyBtnOutline:"로그인",readyBtnPrimary:"계좌 개설",footerAwards:"최근 수상: 최고 스프레드 베팅 브로커, Good Money Guide Awards 2026; 최다 통화쌍 및 종합 우수성, MetaTrader, 모바일 트레이딩 앱, 전문 트레이딩, 리서치 및 TradingView 부문 1위, ForexBrokers.com Awards 2025; 활발한 트레이더를 위한 최고 브로커, Professional Trader Awards 2025; 최고 모바일 트레이딩 플랫폼 및 최고 스프레드 베팅 & CFD 교육 도구, ADVFN International Financial Awards 2025; 수수료 및 비용 1위, ForexBrokers.com Awards 2025.",footerNote2:"2025년 11월 기준 CMC의 트레이딩 및 투자 플랫폼(파트너 포함)에서 200만 명 이상의 고유 사용자 로그인 데이터를 기반으로 합니다.",footerNote3:"6개 주요 통화쌍에서 0.0핍, 300개 이상의 다른 통화쌍에서 25% 스프레드 할인, FX Active 계좌의 경우 10만 달러 명목 가치당 2.50달러의 낮은 고정 커미션.",footerNote4:"2024년 4월 1일부터 2025년 3월 31일까지 전 세계 MetaTrader 4 플랫폼에서 CFD 중간값 거래 체결 시간은 0.018초입니다.",footerNote5:"2024년 9월 23일부터 2025년 3월 31일까지 99.29%의 시장 개장 주문이 제시된 호가로 체결되었습니다.",footerNote6:"2025년 1월부터 3월까지 CMC Markets 고객이 MetaTrader 4 플랫폼에서 거래할 때의 평균 핵심 플랫폼 가동 시간은 98.70%입니다.",goTrade:"거래하기",news:"뉴스",newstitle:"최신 시장 정보를 통해 언제든지 거래 전략을 조정하세요",news1:"암호화폐 뉴스",news2:"최신 경제 지표",news3:"주식시장 뉴스"}};export{e as default};
